{"code":"import numpy as np
from collections import deque
# Build a boolean shape mask: non-zero cells are part of shape
B = (self.grid != 0)
H, W = self.height, self.width
# Compute interior mask: cell has all 4 neighbors in B
interior = np.zeros((H, W), bool)
for y in range(1, H-1):
    for x in range(1, W-1):
        if B[y, x] and B[y-1, x] and B[y+1, x] and B[y, x-1] and B[y, x+1]:
            interior[y, x] = True
# Label interior connected components
labels = -np.ones((H, W), int)
current_label = 0
for y in range(H):
    for x in range(W):
        if interior[y, x] and labels[y, x] == -1:
            # BFS
            queue = deque([(y, x)])
            labels[y, x] = current_label
            while queue:
                cy, cx = queue.popleft()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = cy+dy, cx+dx
                    if 0 <= ny < H and 0 <= nx < W and interior[ny, nx] and labels[ny, nx] == -1:
                        labels[ny, nx] = current_label
                        queue.append((ny, nx))
            current_label += 1
# Map labels to marker colors
label_color = {}
for y in range(H):
    for x in range(W):
        c = self.grid[y, x]
        if c > 1 and interior[y, x]:
            lbl = labels[y, x]
            label_color[lbl] = c
# Fill interior
for y in range(H):
    for x in range(W):
        if interior[y, x]:
            lbl = labels[y, x]
            if lbl in label_color:
                self.grid[y, x] = label_color[lbl]
